class EditableMesh(Object):
    r"""
    Editable Mesh
    
    **C++ Source:**
    
    - **Plugin**: EditableMesh
    - **Module**: EditableMesh
    - **File**: EditableMesh.h
    
    **Editor Properties:** (see get_editor_property/set_editor_property)
    
    - ``subdivision_count`` (int32):  [Read-Write] How many levels to subdivide this mesh.  Zero will turn off subdivisions
    - ``texture_coordinate_count`` (int32):  [Read-Write] The number of texture coordinates stored on the vertices of this mesh
    """
    @property
    def texture_coordinate_count(self):
        r"""
        (int32):  [Read-Only] The number of texture coordinates stored on the vertices of this mesh
        """
        return 0
    @property
    def subdivision_count(self):
        r"""
        (int32):  [Read-Only] How many levels to subdivide this mesh.  Zero will turn off subdivisions
        """
        return 0
    def weld_vertices(self, vertex_i_ds):
        r"""
        x.weld_vertices(vertex_i_ds) -> VertexID
        Weld Vertices
        
        Args:
            vertex_i_ds (Array(VertexID)): 
        
        Returns:
            VertexID: 
        
            out_new_vertex_id (VertexID):
        """
        return VertexID()
    def try_to_remove_vertex(self, vertex_id):
        r"""
        x.try_to_remove_vertex(vertex_id) -> (out_was_vertex_removed=bool, out_new_edge_id=EdgeID)
        Try to Remove Vertex
        
        Args:
            vertex_id (VertexID): 
        
        Returns:
            tuple: 
        
            out_was_vertex_removed (bool): 
        
            out_new_edge_id (EdgeID):
        """
        return (False, EdgeID())
    def try_to_remove_polygon_edge(self, edge_id):
        r"""
        x.try_to_remove_polygon_edge(edge_id) -> (out_was_edge_removed=bool, out_new_polygon_id=PolygonID)
        Try to Remove Polygon Edge
        
        Args:
            edge_id (EdgeID): 
        
        Returns:
            tuple: 
        
            out_was_edge_removed (bool): 
        
            out_new_polygon_id (PolygonID):
        """
